const body = $input.first().json.body || {};
const now = new Date().toISOString();
const required = ['clientName', 'description'];
const missing = required.filter(key => !body[key]);
if (missing.length) {
  return [{ json: { ok: false, status: 'missing_required_fields', missing } }];
}
const job = {
  id: body.id || ('JOB-' + String(Date.now()).slice(-6)),
  createdAt: now,
  clientName: body.clientName,
  clientType: body.clientType || 'particular',
  phone: body.phone || '',
  zone: body.zone || '',
  description: body.description,
  status: body.status || 'nuevo',
  priority: body.priority || 'normal',
  estimatedHours: Number(body.estimatedHours || 1),
  notes: body.notes || ''
};
return [{ json: { ok: true, job } }];
